insert into public.specialties (slug, name, short_name, icon, summary, description, problems, services, faqs, sort_order)
values
('derecho-de-transito', 'Derecho de tránsito', 'Tránsito', 'car', 'Comparendos, impugnación de infracciones, accidentes y defensa ante los organismos de tránsito.', 'Acompañamos a conductores, propietarios y empresas de transporte frente a las autoridades de tránsito. Revisamos cada comparendo y cada actuación administrativa para verificar que se haya respetado el debido proceso, la notificación en término y la validez de la prueba, incluida la proveniente de cámaras de fotodetección. Cuando hay un accidente, orientamos sobre responsabilidades, seguros y reclamaciones, y representamos al cliente en las audiencias que correspondan.', array['Comparendos impuestos sin notificación oportuna o con fallas en la prueba.', 'Fotomultas que llegan al propietario sin identificar al conductor.', 'Accidentes con daños materiales o lesiones y discusión sobre responsabilidad.', 'Suspensión o cancelación de la licencia de conducción.', 'Cobros coactivos y embargos derivados de multas antiguas.']::text[], array['Comparendos y multas.', 'Impugnación de infracciones.', 'Accidentes de tránsito.', 'Defensa en procedimientos administrativos.', 'Recuperación de derechos relacionados con licencias de conducción.']::text[], '[{"q":"¿Puedo impugnar una fotomulta?","a":"Sí, cuando hay razones de hecho o de derecho, por ejemplo fallas en la notificación o en la identificación del infractor. Revisamos el caso concreto y le decimos con franqueza si la impugnación tiene fundamento."},{"q":"¿Cuánto tiempo tengo para actuar frente a un comparendo?","a":"Los términos son cortos y dependen de la etapa del proceso. Lo recomendable es consultarnos apenas reciba la notificación para no perder oportunidades de defensa."},{"q":"¿Qué hago después de un accidente de tránsito?","a":"Conserve las pruebas (fotografías, datos de testigos, informe policial), reporte a su aseguradora y busque asesoría antes de firmar acuerdos o conciliaciones."}]'::jsonb, 1),
('derecho-penal', 'Derecho penal', 'Penal', 'gavel', 'Defensa penal, representación de víctimas y estrategia en cada etapa del proceso.', 'Asumimos la defensa técnica de personas investigadas y la representación de víctimas dentro del sistema penal acusatorio colombiano. Analizamos el caso desde el primer contacto, construimos una estrategia de defensa sustentada en la prueba y acompañamos al cliente en audiencias, entrevistas y diligencias, explicándole en lenguaje claro qué sucede en cada etapa.', array['Citaciones a interrogatorio o a audiencia de imputación.', 'Capturas y solicitudes de medida de aseguramiento.', 'Denuncias que la persona considera infundadas.', 'Víctimas que necesitan ser reconocidas y reparadas dentro del proceso.', 'Preacuerdos, principios de oportunidad y mecanismos de terminación anticipada.']::text[], array['Defensa penal.', 'Asesoría en procesos judiciales.', 'Representación y acompañamiento.', 'Análisis de casos y estrategias de defensa.']::text[], '[{"q":"Me citaron a la Fiscalía, ¿debo ir con abogado?","a":"Es lo recomendable. Antes de cualquier diligencia conviene conocer su calidad dentro del proceso y sus derechos, incluido el de guardar silencio."},{"q":"¿Representan también a víctimas?","a":"Sí. La víctima tiene derecho a la verdad, la justicia y la reparación, y puede intervenir activamente en el proceso con apoderado."},{"q":"¿Pueden garantizar el resultado del proceso?","a":"No. Ningún abogado puede garantizar un resultado judicial. Nos comprometemos con una defensa diligente, técnica y transparente."}]'::jsonb, 2),
('derecho-economico-y-financiero', 'Derecho económico y financiero', 'Económico y financiero', 'landmark', 'Obligaciones, deudas, conflictos con entidades financieras y protección del patrimonio.', 'Asesoramos a personas y empresas en conflictos de contenido económico: obligaciones incumplidas, cobros, reestructuración de deudas, reclamaciones ante entidades financieras y protección de bienes. Revisamos contratos, títulos valores y estados de cuenta para identificar cobros indebidos y proponer rutas de negociación, conciliación o reclamación judicial según convenga.', array['Cobros que no corresponden a lo pactado o con intereses excesivos.', 'Procesos ejecutivos, embargos y riesgo sobre bienes.', 'Deudas difíciles de pagar que requieren reorganización.', 'Reclamaciones ante bancos, aseguradoras y otras entidades vigiladas.', 'Socios o contratantes que incumplen obligaciones económicas.']::text[], array['Asesoría financiera legal.', 'Conflictos económicos.', 'Obligaciones y deudas.', 'Protección de intereses patrimoniales.']::text[], '[{"q":"¿Pueden ayudarme a negociar con el banco?","a":"Sí. Revisamos la obligación, identificamos posibles cobros indebidos y acompañamos la negociación o la reclamación formal ante la entidad o el defensor del consumidor financiero."},{"q":"Me embargaron, ¿qué puedo hacer?","a":"Depende del tipo de proceso y del bien. Existen bienes inembargables y defensas posibles; conviene revisar el expediente cuanto antes."}]'::jsonb, 3),
('derecho-digital-y-tecnologico', 'Derecho digital y tecnológico', 'Digital y tecnológico', 'shield', 'Delitos informáticos, protección de datos, suplantación de identidad y fraudes digitales.', 'Atendemos los conflictos que nacen en internet y en el uso de tecnologías: delitos informáticos, suplantación de identidad, fraudes en compras o transferencias, filtración de datos personales y vulneración de derechos en redes sociales. Orientamos sobre la preservación de evidencia digital, las denuncias y reclamaciones ante las autoridades y plataformas, y las acciones para proteger los datos personales conforme a la Ley 1581 de 2012.', array['Suplantación de identidad en redes sociales, bancos o servicios en línea.', 'Fraudes en compras, transferencias o inversiones por internet.', 'Uso indebido o filtración de datos personales.', 'Acceso abusivo a cuentas o sistemas informáticos.', 'Publicaciones que vulneran la intimidad o la honra.']::text[], array['Delitos informáticos.', 'Protección de datos personales.', 'Suplantación de identidad.', 'Fraudes digitales.', 'Vulneración de derechos en internet.']::text[], '[{"q":"Fui víctima de un fraude por internet, ¿qué hago primero?","a":"Bloquee los productos afectados, conserve capturas, correos y comprobantes, y busque asesoría para presentar la denuncia y las reclamaciones correspondientes."},{"q":"¿Cómo pruebo algo que ocurrió en redes sociales?","a":"La evidencia digital debe preservarse de forma adecuada para que sea útil. Le orientamos sobre cómo conservarla sin alterarla."}]'::jsonb, 4),
('derecho-migratorio-y-visas', 'Derecho migratorio y asesoría de visas', 'Migratorio y visas', 'plane', 'Orientación en solicitudes de visa, documentación y procesos migratorios.', 'Orientamos a personas que desean viajar, residir o regularizar su situación migratoria. Revisamos requisitos, preparamos la documentación de soporte y acompañamos las solicitudes y los recursos ante las autoridades competentes. La decisión sobre una visa corresponde siempre a la autoridad consular o migratoria; nuestro trabajo es que la solicitud se presente completa, coherente y en término.', array['Dudas sobre el tipo de visa adecuado para cada propósito.', 'Solicitudes negadas que pueden revisarse o presentarse de nuevo.', 'Documentación incompleta, vencida o sin apostilla.', 'Extranjeros que necesitan regularizar su permanencia en Colombia.', 'Procesos de reunificación familiar.']::text[], array['Orientación sobre solicitudes de visa.', 'Asesoría en documentación.', 'Procesos migratorios.', 'Acompañamiento en solicitudes y recursos.']::text[], '[{"q":"¿Ustedes aprueban la visa?","a":"No. La decisión es exclusiva de la autoridad consular o migratoria. Le ayudamos a preparar y presentar una solicitud completa y bien sustentada."},{"q":"Me negaron la visa, ¿puedo volver a aplicar?","a":"En muchos casos sí. Revisamos los motivos de la negativa para corregir lo que sea posible antes de una nueva solicitud."}]'::jsonb, 5),
('proteccion-del-buen-nombre', 'Protección del buen nombre y reputación', 'Buen nombre', 'badge-check', 'Rectificación de información falsa, reclamaciones y orientación sobre registros negativos.', 'Protegemos el derecho fundamental al buen nombre y a la honra frente a publicaciones falsas o perjudiciales y frente a registros desactualizados. Presentamos solicitudes de rectificación, reclamaciones ante centrales de información y, cuando procede, acciones de tutela. Orientamos sobre la actualización, corrección o eliminación de historiales negativos únicamente en los casos en que la ley lo permite; no ofrecemos ni garantizamos la eliminación de antecedentes o registros que deban conservarse legalmente.', array['Publicaciones falsas o injuriosas en medios o redes sociales.', 'Reportes negativos en centrales de riesgo con datos inexactos o desactualizados.', 'Información que permanece publicada más allá del tiempo legal.', 'Dudas sobre antecedentes y registros que afectan oportunidades laborales.', 'Necesidad de solicitar rectificación a un medio o a una plataforma.']::text[], array['Protección del buen nombre.', 'Rectificación de información falsa.', 'Reclamaciones por información perjudicial.', 'Asesoría sobre antecedentes y registros negativos.', 'Orientación sobre la eliminación, actualización o corrección de historiales negativos cuando legalmente proceda.']::text[], '[{"q":"¿Pueden borrar mi reporte negativo?","a":"Solo cuando la ley lo permite, por ejemplo si el dato es inexacto, no fue notificado o ya cumplió el término de permanencia. Revisamos su caso y le decimos con claridad si procede."},{"q":"¿Qué hago si publicaron algo falso sobre mí?","a":"El primer paso suele ser una solicitud formal de rectificación. Si no hay respuesta, pueden proceder otras acciones, incluida la tutela."}]'::jsonb, 6)
